fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    // Requires: The input vector must have a length of 0 or more.
    // Ensures: The output vector will have a length of 0 if the input is empty,
    //          or will have a length of 2 * input_length - 1 if the input has more than 1 element.
    //          The output will contain all elements of the input interspersed with the delimiter.
    // Invariant: At each iteration, the result vector contains the first i elements of the input
    //            followed by (i - 1) delimiters, where i is the current index in the loop.
    // Decreases: The length of the input vector, ensuring termination of the loop.
    
    // If the input array has length 0 or 1, return it unchanged
    if numbers.len() <= 1 {
        return numbers;
    }

    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(2 * numbers.len() - 1);

    // Iterate through the input numbers
    for (i, &num) in numbers.iter().enumerate() {
        // Push the current number
        result.push(num);
        // If it's not the last element, push the delimiter
        if i < numbers.len() - 1 {
            result.push(delimiter);
        }
    }

    result
}